Output: {"entities": [{"text": "Oberste Gerichtshof", "type": "organisation", "start": 9, "end": 28}, {"text": "Oberlandesgerichts Linz", "type": "organisation", "start": 582, "end": 605}, {"text": "Landesgerichts Wels", "type": "organisation", "start": 734, "end": 753}]}

